const EXTRA = { ...EXTRA_SPECS_1, ...EXTRA_SPECS_2, ...EXTRA_SPECS_3 };
for (const d of DEVICES) {
  const ex = EXTRA[d.id];
  if (!ex) continue;
  if (ex.m) { d.scores.memoria = ex.m[0]; d.details.memoria = ex.m[1]; }
  if (ex.e) { d.scores.energia = ex.e[0]; d.details.energia = ex.e[1]; }
}
// Segmento de categoría usado en la URL (/celulares/... o /computadoras/...)
function categorySlug(type) {
  if (type === "Celular") return "celulares";
  if (type === "Tablet") return "tablets";
if (type === "Smartwatch") return "relojes";
return "computadoras";
}


// Añade slug único (con desambiguación por si dos nombres generan el mismo slug)
const seenSlugs = new Map();
for (const d of DEVICES) {
  let base = slugify(d.name);
  let slug = base;
  let n = 2;
  while (seenSlugs.has(slug) && seenSlugs.get(slug) !== d.id) {
    slug = `${base}-${n++}`;
  }
  seenSlugs.set(slug, d.id);
  d.slug = slug;
  d.slugType = categorySlug(d.type);
}

export function overallOf(device) {
const vals = CATS.map((c) => device.scores[c.key]).filter((v) => typeof v === "number");
return Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
}

export function getDeviceBySlug(slugType, slug) {
  return DEVICES.find((d) => d.slugType === slugType && d.slug === slug) || null;
}

// Los slugs son únicos en todo el catálogo (ver deduplicación arriba), así
// que también se puede buscar sin conocer la categoría (usado en la URL de
// comparación /comparar/:slugA-vs-:slugB).
export function getDeviceBySlugAny(slug) {
  return DEVICES.find((d) => d.slug === slug) || null;
}

export function getDevicesByType(type) {
  return DEVICES.filter((d) => d.type === type);
}

export { CATS, DEVICES };
